mapper.select:
SELECT COALESCE(max(
octet_length(CAST(#{params.DestinationPath} AS text))
+ octet_length(path)
- octet_length(CAST(#{params.SourcePath} AS text))
), 0) AS max_path_bytes
FROM session_resources
WHERE workspace_uuid = #{params.WorkspaceUUID}
AND session_uuid = #{params.SessionUUID}
AND deleted_at IS NULL
AND (
path = #{params.SourcePath}
OR left(path, char_length(#{params.SourcePath}) + 1) = #{params.SourcePath} || '/'
)

SELECT EXISTS (
SELECT 1
FROM session_resources
WHERE workspace_uuid = #{params.WorkspaceUUID}
AND session_uuid = #{params.SessionUUID}
AND deleted_at IS NULL
AND payload IS NOT NULL
AND (
path = #{params.SourcePath}
OR left(path, char_length(#{params.SourcePath}) + 1) = #{params.SourcePath} || '/'
)
) AS contains_input

SELECT id
FROM session_resources
WHERE workspace_uuid = #{params.WorkspaceUUID}
AND session_uuid = #{params.SessionUUID}
AND deleted_at IS NULL
AND (expires_at IS NULL OR expires_at > now())
AND (
path = #{params.DestinationPath}
OR left(path, char_length(#{params.DestinationPath}) + 1) = #{params.DestinationPath} || '/'
)
LIMIT 1

