UPDATE session_resources
SET path = #{params.DestinationPath} || substring(path FROM char_length(#{params.SourcePath}) + 1),
parent_path = CASE
WHEN path = #{params.SourcePath} THEN #{params.DestinationParentPath}
ELSE #{params.DestinationPath} || substring(parent_path FROM char_length(#{params.SourcePath}) + 1)
END,
updated_at = #{params.Now}
WHERE workspace_uuid = #{params.WorkspaceUUID}
AND session_uuid = #{params.SessionUUID}
AND deleted_at IS NULL
AND (
path = #{params.SourcePath}
OR left(path, char_length(#{params.SourcePath}) + 1) = #{params.SourcePath} || '/'
)

